<script lang="ts">
 import type { Model } from "../engine/types.js"; import { MACRO_ROUTES, type Effort } from "../article/macroPricing.js";
 import { MODELS,EFFORTS,CONFIGS,CONFIG_UNLOCKS,newCampaign,typesForWeek,newlyUnlocked,weekTasks,previewChoice,resolveWeek,advanceWeek,enterEndless,assignmentFor,requiredRate,type Assignment,type CampaignTask,type ConfigId,type Difficulty,type TaskType } from "./dispatchEngine.js";
 interface Props{onback:()=>void} let {onback}:Props=$props();
 let campaign=$state(newCampaign()), difficulty=$state<Difficulty>("easy"), practice=$state(false), started=$state(false), staffing=$state<string|null>(null), draft=$state<Assignment>({model:"sonnet",effort:"high"}), subPrompt=$state(false), tasks=$state<CampaignTask[]>([]), runIndex=$state(0), hovered=$state<Assignment|null>(null);
 const faces:Record<Model,string>={haiku:"🫘",sonnet:"🧠",opus:"🧠✨",fable:"🔮"}; const guide:Record<Model,string>={haiku:"tiny, fast & literal",sonnet:"steady engineering judgment",opus:"deep hypothesis search",fable:"experimental premium brain"};
 let types=$derived(typesForWeek(campaign.week)), report=$derived(campaign.reports[campaign.reports.length-1]), activeTask=$derived(tasks[runIndex]);
 function money(n:number){return `$${n.toFixed(2)}`} function reset(){campaign=newCampaign();started=true;staffing="Development";draft={model:"sonnet",effort:"high"}}
 function beginWeek(){campaign={...campaign,phase:"setup"};const fresh=newlyUnlocked(campaign.week);if(campaign.week===1)staffing="Development";else if(campaign.week===2&&campaign.subagents===null)subPrompt=true;else staffing=fresh.find(t=>!campaign.assignments[t.name])?.name??null}
 function decideSubagents(yes:boolean){campaign={...campaign,subagents:yes};subPrompt=false;if(yes)staffing=newlyUnlocked(campaign.week)[0]?.name??null}
 function saveAssignment(){if(!staffing)return;campaign={...campaign,assignments:{...campaign.assignments,[staffing]:draft}};const next=newlyUnlocked(campaign.week).find(t=>!campaign.assignments[t.name]);staffing=campaign.subagents===true&&next?next.name:null;draft={model:"sonnet",effort:"medium"}}
 function startRun(){tasks=weekTasks(campaign.week,difficulty);runIndex=0;campaign={...campaign,phase:"running"}; if(typeof window==="undefined"||matchMedia("(prefers-reduced-motion: reduce)").matches){finishRun();return} const tick=setInterval(()=>{runIndex++;if(runIndex>=tasks.length){clearInterval(tick);finishRun()}},240)}
 function finishRun(){const out=resolveWeek(campaign,difficulty,tasks,practice);campaign=out.state}
 function next(){campaign=advanceWeek(campaign)} function toggleConfig(id:ConfigId){campaign={...campaign,configs:campaign.configs.includes(id)?campaign.configs.filter(x=>x!==id):[...campaign.configs,id]}}
 function taskByName(name:string):TaskType{return types.find(t=>t.name===name)??types[0]} function choicePreview(t:TaskType,a:Assignment){return previewChoice(t,a,campaign.configs)} function offeredConfig():ConfigId{return CONFIG_UNLOCKS[Math.min(campaign.week-3,CONFIG_UNLOCKS.length-1)]} function staffingPreview(){return choicePreview(taskByName(staffing??"Development"),hovered??draft)}
</script>
<section class="td-shell"><header><button class="link" onclick={onback}>← map</button><div><small>THE SIX-WEEK QUARTER</small><strong>DON'T GET REPLACED</strong></div><b>{started?campaign.endless?`PLAYGROUND · WEEK ${campaign.week}`:`WEEK ${campaign.week}/6`:"MONDAY, 9:01"}</b></header>
{#if !started}<main class="paper hero"><span class="stamp">JOB<br>FRAGILE</span><p class="eyebrow">A TURN-BASED AI ROUTING CAMPAIGN</p><h1>Right brain.<br><em>Keep your job.</em></h1><p>Build a tiny team, route each kind of work, and make six increasingly spicy weeks cost less than panic-Opus.</p><div class="chips">{#each ["easy","medium","hard"] as d}<button class:active={difficulty===d} onclick={()=>difficulty=d as Difficulty}>{d}</button>{/each}</div><label><input type="checkbox" bind:checked={practice}> Practice mode — job security never reaches zero</label><button class="primary" onclick={reset}>Begin quarter →</button></main>
{:else if campaign.phase==="briefing"}<main class="campaign"><section class="hud paper"><div><small>JOB SECURITY</small><strong>{Math.round(campaign.security)}%</strong><i><b style={`width:${campaign.security}%`}></b></i></div><div><small>THIS WEEK'S BAR</small><strong>{requiredRate(campaign.week,difficulty)}%</strong></div><div><small>TOTAL SAVED VS PANIC</small><strong class="green">{money(campaign.totalSaved)}</strong></div><div><small>ACTIVE CONFIGS</small><strong>{campaign.configs.length}</strong></div></section><section class="paper briefing"><p class="eyebrow">WEEK {campaign.week} BRIEFING · NEVER AUTO-ADVANCES</p><h1>{campaign.week>=6?"Pressure week.":"Here comes the work."}</h1><div class="roster">{#each types as t}<article><span>{t.icon}</span><b>{t.name}</b><small>~{weekTasks(campaign.week,difficulty).filter(x=>x.name===t.name).length} · {MACRO_ROUTES[t.routeIndex].judgment}</small></article>{/each}</div><h3>Your team</h3><div class="team">{#each types as t}{@const a=assignmentFor(campaign,t.name)}<span>{t.name}: <b>{a?`${a.model}·${a.effort}`:"unstaffed"}</b></span>{/each}</div>{#if campaign.week>=3}<h3>Config unlocked this week</h3><button class:active={campaign.configs.includes(offeredConfig())} class="config" onclick={()=>toggleConfig(offeredConfig())}>✓ {CONFIGS[offeredConfig()].name} <small>{CONFIGS[offeredConfig()].effect} · click to toggle</small></button>{/if}<button class="primary" onclick={beginWeek}>Start week →</button></section></main>
{:else if campaign.phase==="setup"}<main class="campaign"><section class="paper setup"><p class="eyebrow">SETUP · CLICK CHIPS TO ASSIGN WORK</p><h1>Build this week's team.</h1>{#if subPrompt}<div class="modal"><h2>Bring in subagents?</h2><p>A subagent handles one kind of task at its own model + effort.</p><button class="primary" onclick={()=>decideSubagents(true)}>Yes, specialize</button><button onclick={()=>decideSubagents(false)}>No, use Development for all</button></div>{:else if staffing}{@const t=taskByName(staffing)}<div class="modal"><p class="eyebrow">{campaign.week===1?"TUTORIAL":"NEW TASK TYPE"}</p><h2>Who handles {staffing}?</h2><p>{MACRO_ROUTES[t.routeIndex].judgment}</p><p class="eyebrow">MODEL</p><div class="brains">{#each MODELS as m}<button class:active={draft.model===m} onmouseenter={()=>hovered={...draft,model:m}} onfocus={()=>hovered={...draft,model:m}} onclick={()=>draft={...draft,model:m}}><span>{faces[m]}</span><b>{m}</b><small>{guide[m]}</small></button>{/each}</div><p class="eyebrow">EFFORT</p><div class="chips">{#each EFFORTS as e}<button class:active={draft.effort===e} onmouseenter={()=>hovered={...draft,effort:e}} onclick={()=>draft={...draft,effort:e}}>{e}</button>{/each}</div><div class={`preview ${staffingPreview().verdict}`}><b>{staffingPreview().verdict==="good"?"GOOD FIT ✓":staffingPreview().verdict==="bad"?"UNDERPOWERED → REWORK":"PASSES · OVERKILL"}</b> {money(staffingPreview().cost)}{#if difficulty==="easy"}<small>suggested: {MACRO_ROUTES[t.routeIndex].model}·{MACRO_ROUTES[t.routeIndex].effort}</small>{/if}</div><button class="primary" onclick={saveAssignment}>Assign {staffing} →</button></div>{:else}<div class="roster">{#each types as t}{@const a=assignmentFor(campaign,t.name)}{@const p=a?choicePreview(t,a):null}<article><span>{t.icon}</span><b>{t.name}</b><small>{a?.model}·{a?.effort} · {p?.verdict} · {p?money(p.cost):"—"}</small><i><b style={`width:${["haiku","sonnet","opus","fable"].indexOf(MACRO_ROUTES[t.routeIndex].model)*25+25}%`}></b></i></article>{/each}</div><button class="primary" onclick={startRun}>Run the week →</button>{/if}</section><aside class="paper guide"><p class="eyebrow">BRAIN GUIDE</p>{#each MODELS as m}<div><span>{faces[m]}</span><b>{m}</b><small>{guide[m]}</small></div>{/each}<p>Underpowered work fails. Oversized brains pass, but eat the savings.</p></aside></main>
{:else if campaign.phase==="running"}<main class="paper running"><p class="eyebrow">THE WEEK IS IN MOTION</p><h1>Day {activeTask?.day??5} / 5</h1><div class="counter">{money(tasks.slice(0,runIndex).reduce((n,t)=>{const a=assignmentFor(campaign,t.name)??{model:"haiku",effort:"low"};return n+choicePreview(t,a).cost},0))}</div><div class="stream">{#each tasks.slice(Math.max(0,runIndex-3),runIndex+1) as t}{@const a=assignmentFor(campaign,t.name)??{model:"haiku",effort:"low"}}{@const p=choicePreview(t,a)}<article class={p.verdict}><span>{t.icon}</span><b>{t.name}</b><strong>{p.verdict==="bad"?"FAIL ↩":"PASS ✓"}</strong><small>{a.model}·{a.effort} · {money(staffingPreview().cost)}</small></article>{/each}</div></main>
{:else if campaign.phase==="report" && report}<main class="paper report"><p class="eyebrow">WEEK {report.week} REPORT CARD</p><h1>{Math.round(report.successRate)}% success</h1><div class="scores"><div><small>SPENT</small><b>{money(report.spent)}</b><small>budget {money(report.budget)}</small></div><div><small>SAVED VS PANIC OPUS·HIGH</small><b class="green">{money(report.saved)}</b><small>baseline {money(report.baseline)}</small></div><div><small>JOB SECURITY</small><b>{report.securityDelta>=0?"+":""}{report.securityDelta}</b><small>now {Math.round(campaign.security)}%</small></div></div><p>{report.spent>report.budget?"Over budget: no security restoration this week.":"Right-sized brains kept the work moving for less."}</p><button class="primary" onclick={next}>{campaign.week>=6?"See quarter result →":"Continue to next week →"}</button></main>
{:else if campaign.phase==="won"}<main class="paper hero"><p class="eyebrow">QUARTER COMPLETE · YOU SURVIVED</p><h1>Still human.<br><em>{money(campaign.totalSaved)} saved.</em></h1><p>You routed judgment where it mattered and made the cache configs compound.</p><button class="primary" onclick={()=>campaign=enterEndless(campaign)}>Enter Playground →</button><button onclick={reset}>Replay campaign</button></main>
{:else}<main class="paper hero"><p class="eyebrow">A GENTLE AUTOMATION NOTICE</p><h1>You got<br>replaced-ish.</h1><p>Your replacement is three cron jobs in a trench coat. Try a stronger route mix; the first weeks will still give you room to learn.</p><button class="primary" onclick={reset}>Retry quarter →</button></main>{/if}</section>
<style>
 :global(body:has(.td-shell)){background:var(--toy-cream)!important;color:var(--toy-ink)!important}.td-shell{min-height:100dvh;background:var(--toy-cream);color:var(--toy-ink);padding:16px;box-sizing:border-box;font-family:var(--font-body)}button{font:inherit;color:inherit;cursor:pointer}.td-shell>header{max-width:1120px;margin:auto;display:flex;justify-content:space-between;align-items:center;text-align:center}.td-shell>header strong{display:block;font:900 clamp(20px,4vw,38px)/.9 var(--font-display)}.link{border:0;background:none;font-weight:900}.paper{background:var(--toy-paper);border:2px solid var(--toy-ink);border-radius:18px;box-shadow:7px 8px 0 var(--toy-ink)}.hero,.report,.running{max-width:820px;margin:6vh auto;padding:clamp(28px,6vw,64px);text-align:center;position:relative}.hero h1,.briefing h1,.setup h1,.report h1{font:900 clamp(45px,8vw,84px)/.86 var(--font-display);margin:.2em}.hero em,.green{color:var(--toy-green-ink);font-style:normal}.stamp{position:absolute;right:30px;transform:rotate(8deg);border:3px solid var(--toy-red-ink);color:var(--toy-red-ink);padding:8px;font-weight:900}.eyebrow{font-size:12px;font-weight:900;letter-spacing:.12em}.primary{display:inline-block;background:var(--toy-green);border:2px solid var(--toy-ink);border-radius:10px;box-shadow:3px 4px var(--toy-ink);padding:12px 20px;font-weight:900;margin:18px 8px}.chips{display:flex;justify-content:center;margin:14px}.chips button,.config{border:2px solid var(--toy-ink);background:var(--toy-cream);padding:9px 15px;text-transform:capitalize}.active{background:var(--toy-gold)!important}.campaign{max-width:1120px;margin:18px auto;display:grid;grid-template-columns:1fr 250px;gap:14px}.hud{grid-column:1/-1;display:grid;grid-template-columns:repeat(4,1fr);padding:12px}.hud div{padding:8px 15px;border-right:1px dashed var(--toy-dash)}.hud small,.scores small{display:block}.hud strong{font:900 28px var(--font-display)}.hud i,.roster i{height:9px;background:var(--toy-cream);border:1px solid;display:block}.hud i b,.roster i b{display:block;height:100%;background:var(--toy-green)}.briefing,.setup{grid-column:1/-1;padding:clamp(20px,4vw,45px);text-align:center}.setup{grid-column:1}.roster{display:grid;grid-template-columns:repeat(auto-fit,minmax(155px,1fr));gap:10px}.roster article{border:2px solid;border-radius:12px;padding:12px;background:var(--toy-cream);text-align:left}.roster article>*{display:block}.roster article>span{font-size:25px}.roster small,.team{color:var(--toy-muted)}.team{display:flex;flex-wrap:wrap;gap:8px;justify-content:center}.team span{background:var(--toy-blue-soft);padding:7px}.config small{display:block}.modal{border:2px dashed;padding:20px;background:var(--toy-cream)}.brains{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}.brains button{border:2px solid;border-radius:12px;background:var(--toy-paper);padding:12px}.brains span,.brains small{display:block}.brains b{text-transform:capitalize}.preview{margin:16px;padding:12px;border:2px solid}.preview.good{background:var(--toy-green-soft)}.preview.bad{background:var(--toy-red-soft)}.preview.expensive{background:var(--toy-gold-soft)}.preview small{display:block}.guide{padding:15px}.guide div{display:grid;grid-template-columns:34px 65px 1fr;padding:9px 0;border-bottom:1px dashed}.stream{display:flex;gap:10px;justify-content:center}.stream article{padding:13px;border:2px solid;border-radius:12px;animation:arrive .22s}.stream article>*{display:block}.stream .good{background:var(--toy-green-soft)}.stream .bad{background:var(--toy-red-soft)}.counter{font:900 54px var(--font-display)}.scores{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.scores div{padding:18px;background:var(--toy-cream);border:2px dashed}.scores b{font:900 30px var(--font-display)}@keyframes arrive{from{transform:translateX(30px);opacity:0}}@media(max-width:750px){.campaign{grid-template-columns:1fr}.setup,.guide{grid-column:1}.hud{grid-template-columns:1fr 1fr}.brains{grid-template-columns:1fr 1fr}.scores{grid-template-columns:1fr}.stamp{display:none}}@media(prefers-reduced-motion:reduce){*,*::before,*::after{animation:none!important;transition:none!important}}
</style>
